for name in ('CurrentTask','ConversationHandoff','SessionLog','DevelopmentSchedule'):
 p=ROOT/'ProjectDocs/AI'/f'{name}.md';text=p.read_text();assert text==(BASE/'Sources/Before'/p.relative_to(ROOT)).read_text()
 p.write_text(entry+text if name in ('CurrentTask','ConversationHandoff') else (text.rstrip()+'\n\n'+entry).rstrip()+'\n')
for relative,boundary in [('ProjectDocs/AI/AndroidGameplayProfile/R1/Usage.md','## 2026-10-03 — daily-reward build pin'),('ProjectDocs/AI/AndroidGameplayJourney/R1/DeviceChecklist.md','## Device execution matrix')]:
 p=ROOT/relative;s=p.read_text();assert s==(BASE/'Sources/Before'/relative).read_text();end=s.index(boundary);current,history=s[:end],s[end:]
 current=current.replace('round-lifecycle-recovery R2','settings-recovery R2').replace('round lifecycle recovery Android refresh R2','settings recovery Android refresh R2').replace('RoundLifecycleRecovery/R2AndroidRefresh','SettingsRecovery/R2AndroidRefresh').replace('linked round lifecycle R2','linked Settings R2').replace('61native-method','68native-method').replace('766,031,502',size).replace(old['sha256'],h)
 note=f'''\n\n## 2026-10-03 — Settings recovery build pin

[Current Settings R2 results](../../SettingsRecovery/R2AndroidRefresh/TestResults.md) verify {size} bytes/SHA256 `{h}`, original development certificate, 68 native owners/six callbacks, 160 fresh Unity Edit checks and {checks} mocked offline checks. Prior same-source 396 runtime/service checks remain separate. Previous round lifecycle APK/sidecar is retained; earlier dated pins remain historical. Four preferences commit before adoption; rejected saves preserve the switch/feedback state and existing standalone/paused Settings root. Existing localized rejection panel and owned callback/reentry guard are packaged. All 18 physical rows still require native touches, disposable-profile isolation and lifecycle/recovery evidence. No physical audibility/haptics/notifications or commercial acceptance claim.\n'''
 p.write_text((current+history).rstrip()+note)
for name in ('Build.unity.log','Build.launcher.log'):shutil.copy2(Path('/tmp/lor-settings-android-refresh-r2/build')/name,QA/'Build'/name)
for name in ('unity.log','launcher.log'):shutil.copy2(Path('/tmp/lor-settings-android-refresh-r2/Policy')/name,QA/'Policy'/name)
patch=[]
for original in sorted((BASE/'Sources/Before').rglob('*')):
 if original.is_file():
  rel=original.relative_to(BASE/'Sources/Before');patch.extend(difflib.unified_diff(original.read_text().splitlines(True),(ROOT/rel).read_text().splitlines(True),fromfile='a/'+str(rel),tofile='b/'+str(rel)))
(BASE/'Sources/HandoffChanges.patch').write_text(''.join(patch))
print('Verified Settings APK results and eight handoff/tool files recorded; earlier history retained.')
